/**
 * Recorded narration for the Kangla landmarks, in English, Hindi and Meiteilon.
 *
 * The tracks are static MP3s under `public/audio/kangla/<lang>/`, generated by
 * `npm run audio:kangla` (OpenAI TTS) or `npm run audio:kangla:indic`
 * (ai4bharat/indic-parler-tts, offline). Regenerating is reproducible: the
 * source text below is the same text those scripts read.
 *
 * Why this lives in its own module: two different surfaces show the same three
 * landmarks under two different sets of ids — the Google 3D explorer
 * (`kanglaPlaces`) and the reconstruction experience (`kanglaStops`). Keeping
 * the tracks here, with an alias table, means the audio is written once and
 * neither surface owns it.
 */

export type NarrationLanguage = "en" | "hi" | "mni";

export interface NarrationTrack {
  /** The narration, in that language — also shown on screen. */
  text: string;
  /** Path under `public/`. */
  audio: string;
}

export type NarrationSet = Record<NarrationLanguage, NarrationTrack>;

/**
 * `lang` is the BCP-47 tag, so assistive tech switches voice and the browser
 * picks the right font. `className` pulls in the matching webfont for scripts
 * the body face does not cover.
 */
export const narrationLanguages: {
  code: NarrationLanguage;
  label: string;
  lang: string;
  className?: string;
}[] = [
  { code: "en", label: "English", lang: "en-IN" },
  { code: "hi", label: "हिन्दी", lang: "hi-IN", className: "font-devanagari" },
  { code: "mni", label: "ꯃꯩꯇꯩꯂꯣꯟ", lang: "mni-Mtei", className: "font-mayek" },
];

