/**
 * The Google 3D explorer names the same landmarks differently, and covers five
 * more that have no recording yet. Anything absent here simply shows no
 * narration control, which is the honest outcome.
 */
const PLACE_ALIASES: Record<string, string> = {
  "kangla-sha": "guardians",
  "pakhangba-laishang": "pakhangba",
  "western-gate": "western-gate",
};

/** The tracks for a landmark id from either surface, or `undefined`. */
export function narrationFor(id: string | null | undefined): NarrationSet | undefined {
  if (!id) return undefined;
  return kanglaNarration[PLACE_ALIASES[id] ?? id];
}
